            tool,
            toolUse.input,
            { abortSignal: abortSignal ?? new AbortController().signal, toolUseId: toolUse.id },
          )

          yield {
            type: 'tool_result',
            toolUseId: toolUse.id,
            result,
          }

          toolResultContents.push({
            type: 'tool_result',
            tool_use_id: toolUse.id,
            content: result.output,
            ...(result.error ? { is_error: true } : {}),
          })
        } catch (error) {
